#include "cinderwatch/policy/policy.h"
#include <cassert>
int main(){auto ip=cinderwatch::core::parse_ipv4("192.0.2.1");assert(ip);auto bad_ip=cinderwatch::core::parse_ipv4("999.2.3.4");assert(!bad_ip);auto fw=cinderwatch::rules::parse_firewall("-A INPUT -p tcp --dport 22 -j ACCEPT\n-A INPUT -j DROP\n");assert(fw.rules.size()==2);auto bad_fw=cinderwatch::rules::parse_firewall("-A INPUT -s 300.1.1.1 -j ACCEPT\n");assert(!bad_fw.diagnostics.empty());auto ids=cinderwatch::rules::parse_ids_rules("alert tcp any any -> any 80 (msg:\"web\"; content:\"Host\"; sid:1; rev:1;)\n");assert(ids.rules.size()==1);auto bad_ids=cinderwatch::rules::parse_ids_rules("alert tcp any any -> any 80 msg:\"missing block\";\n");assert(!bad_ids.diagnostics.empty());auto st=cinderwatch::ioc::load_text("# block\nexample.com\n198.51.100.0/24\n");assert(st.indicators.size()==2);auto p=cinderwatch::policy::parse_ini("[network]\nallowed_networks=10.0.0.0/8\nrequired_firewall_posture=default deny\n","test");assert(!p.items.empty());auto malformed=cinderwatch::packet::analyze_bytes(std::vector<uint8_t>{1,2,3});assert(!malformed.report.diagnostics.empty());}
